	@Test
	void refusedNumericGrowthPreservesExistingStateAndReleasesOnClose() {
		LmdbQueryMemoryManager manager = installManager();
		SyntheticValueSource source = source();
		RowState row = row(source);
		LmdbNativeKernelHooks hooks = hooks(row, AggregateSpec.slot("sum", 0, false, AggKind.SUM));
		LmdbQueryMemoryManager.Reservation blocker = null;
		try {
			hooks.accumulateNumeric(0, 0, 1L);
			Literal firstSum = hooks.numericSumAt(0, 0);
			long firstCount = hooks.numericCountAt(0, 0);
			boolean firstError = hooks.numericErrorAt(0, 0);
			assertNotNull(firstSum, "the accepted first group must retain its sum");
			LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
			long available = manager.perQueryMaxBytes() - ledger.usedBytes();
			assertTrue(available > 1L, "the refusal fixture needs one byte of headroom");
			blocker = ledger.reserve(available - 1L, null);
			assertNotNull(blocker, "the fixture must occupy the remaining query budget");
			assertThrows(LmdbNativeKernelPartitions.ParallelKernelDecline.class,
					() -> hooks.accumulateNumeric(0, 16, 2L));
			assertEquals(firstSum, hooks.numericSumAt(0, 0), "refusal must preserve the accepted sum");
			assertEquals(firstCount, hooks.numericCountAt(0, 0), "refusal must preserve the accepted count");
			assertEquals(firstError, hooks.numericErrorAt(0, 0), "refusal must preserve the accepted error state");
			assertNull(hooks.numericSumAt(0, 16), "refused group must not retain a sum");
			assertEquals(0L, hooks.numericCountAt(0, 16), "refused group must not retain a count");
			assertFalse(hooks.numericErrorAt(0, 16), "refused group must not retain an error");
		} finally {
			if (blocker != null) {
				blocker.close();
			}
			close(hooks, row, source);
		}
		assertEquals(0L, manager.usedBytes(), "refused hook state must release every reservation");
	}

