	@Test
	void serialSampleAndConcatChargeRetainedUnicodePayloads() {
		LmdbQueryMemoryManager manager = installManager();
		SyntheticValueSource source = source();
		Literal value = SimpleValueFactory.getInstance().createLiteral("λ🧭e\u0301");
		long valueId = source.internComputedValue(value);
		assertEquals(value, source.lazyValue(valueId), "the runtime term authority must round-trip the exact RDF term");

		RowState row = new RowState(source, LAYOUT, EmptyBindingSet.getInstance());
		assertTrue(NativeRowSeeder.seed(row.slots, LAYOUT, row.base, source), "the empty entry row must seed cleanly");
		assertEquals(0L, row.boundMask(), "the seeded row begins with no bound slots");
		assertEquals(LmdbNativeAggregateCompiler.UNKNOWN, row.id(0), "the seeded input begins unbound");
		assertTrue(row.bind(0, valueId), "the mapped Unicode input must bind to its original ID");

		LmdbNativeKernelHooks hooks = hooks(row,
				AggregateSpec.slot("sample", 0, false, AggKind.SAMPLE),
				AggregateSpec.groupConcat("all", 0, false, "🧩"),
				AggregateSpec.groupConcat("distinct", 0, true, "🧩"));
		long afterConstruction = manager.usedBytes();
		long afterSample;
		long afterFirstConcat;
		try {
			hooks.accumulateRow(0, 0);
			assertEquals(value, hooks.rowAggregateResult(0, 0), "SAMPLE must retain the admitted Unicode term");
			afterSample = manager.usedBytes();
			assertTrue(afterSample > afterConstruction, "the SAMPLE owner must charge its retained value");

			hooks.accumulateRow(1, 0);
			afterFirstConcat = manager.usedBytes();
			for (int segment = 1; segment < 40; segment++) {
				hooks.accumulateRow(1, 0);
			}
			for (int segment = 0; segment < 40; segment++) {
				hooks.accumulateRow(2, 0);
			}

			String repeated = String.join("🧩", Collections.nCopies(40, value.stringValue()));
			assertAll(
					() -> assertTrue(afterFirstConcat > afterSample,
							"the FULL GROUP_CONCAT payload must be charged after SAMPLE warms the shared value cache"),
					() -> assertEquals(value, hooks.rowAggregateResult(0, 0)),
					() -> assertEquals(repeated, hooks.rowAggregateResult(1, 0).stringValue(),
							"FULL GROUP_CONCAT must preserve every Unicode segment and separator"),
					() -> assertEquals(value.stringValue(), hooks.rowAggregateResult(2, 0).stringValue(),
							"DISTINCT GROUP_CONCAT must retain exactly one RDF-equal input"));
		} finally {
			close(hooks, row, source);
		}
		assertEquals(0L, manager.usedBytes(), "serial hook and generated-value owners must release on close");
	}

	@Test
	void serialDistinctConcatSpillsExactMembershipAndRetainsFirstEncounterOrder() {
		LmdbQueryMemoryManager previousManager = LmdbNativeHashJoin.queryMemoryOverride;
		String previousGroupLimit = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		String previousGroupsEnabled = System.getProperty(NativeCountGroupStore.ENABLED_PROPERTY);
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(8L << 20, 8L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "16384");
		System.setProperty(NativeCountGroupStore.ENABLED_PROPERTY, "true");
		SyntheticValueSource source = source();
		RowState row = row(source);
		LmdbNativeKernelHooks hooks = null;
		long[] sharedIndexSnapshot = new long[2];
		try {
			List<Long> ids = new ArrayList<>(512);
			List<String> terms = new ArrayList<>(512);
			for (int index = 0; index < 512; index++) {
				String text = "term-" + index + "-λ🧭";
				Literal value = SimpleValueFactory.getInstance().createLiteral(text);
				long id = source.internComputedValue(value);
				assertEquals(value, source.lazyValue(id), "every exact RDF term must round-trip before hook admission");
				ids.add(id);
				terms.add(text);
			}
			hooks = hooks(row, AggregateSpec.slot("warm", 0, false, AggKind.SAMPLE),
					AggregateSpec.groupConcat("distinct", 0, true, "🧩"));
			for (int index = 0; index < ids.size(); index++) {
				hooks.setAggregateInput(0, ids.get(index));
				hooks.accumulateRow(0, index);
			}
			long warmedPayloadBaseline = manager.usedBytes();
			assertTrue(warmedPayloadBaseline > 0L,
					"the source and decoded-value cache must be warm before membership accounting begins");
			sharedIndexSnapshot[0] = NativeExpressionDomain.SPILL_FILES_CREATED.get();
			sharedIndexSnapshot[1] = NativeExpressionDomain.SPILL_FILES_DELETED.get();
			for (long id : ids) {
				hooks.setAggregateInput(0, id);
				hooks.accumulateRow(1, 0);
			}
			for (int index = ids.size() - 1; index >= 0; index--) {
				hooks.setAggregateInput(0, ids.get(index));
				hooks.accumulateRow(1, 0);
			}
			String expected = String.join("🧩", terms);
			long sharedIndexFilesDuring = NativeExpressionDomain.SPILL_FILES_CREATED.get();
			long sharedIndexDeletesDuring = NativeExpressionDomain.SPILL_FILES_DELETED.get();
			LmdbNativeKernelHooks activeHooks = hooks;
			assertAll("DISTINCT membership remains bounded without changing exact terms or encounter order",
					() -> assertTrue(manager.usedBytes() > warmedPayloadBaseline,
							"the retained membership and concatenated payload must be charged after cache warmup"),
					() -> assertTrue(sharedIndexFilesDuring > sharedIndexSnapshot[0],
							"the exact shared-key membership index must spill after cache warmup and before rendering"),
					() -> assertTrue(sharedIndexFilesDuring > sharedIndexDeletesDuring,
							"spill files remain owned during accumulation even when index growth deletes replaced indexes"),
					() -> assertEquals(expected, activeHooks.rowAggregateResult(1, 0).stringValue(),
							"repeated IDs must not duplicate output and the first RDF-term order must be preserved"));
		} finally {
			if (hooks != null) {
				close(hooks, row, source);
			} else {
				row.closeDecodedInputs();
				source.executionContext().close();
			}
			LmdbNativeHashJoin.queryMemoryOverride = previousManager;
			restoreProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousGroupLimit);
			restoreProperty(NativeCountGroupStore.ENABLED_PROPERTY, previousGroupsEnabled);
		}
		assertEquals(NativeExpressionDomain.SPILL_FILES_CREATED.get() - sharedIndexSnapshot[0],
				NativeExpressionDomain.SPILL_FILES_DELETED.get() - sharedIndexSnapshot[1],
				"closing the hook deletes every exact-membership spill file created after warmup");
		assertEquals(0L, manager.usedBytes(), "closing hooks releases membership, result, decoder and source owners");
	}

	@Test
	void serialConcatCancellationClosesSpilledUnicodeAndDistinctState() {
		LmdbQueryMemoryManager manager = installManager();
		SyntheticValueSource source = source();
		Literal value = SimpleValueFactory.getInstance().createLiteral("λ🧭e\u0301");
		long valueId = source.internComputedValue(value);
		RowState row = new RowState(source, LAYOUT, EmptyBindingSet.getInstance());
		assertTrue(NativeRowSeeder.seed(row.slots, LAYOUT, row.base, source));
		assertEquals(0L, row.boundMask());
		assertEquals(LmdbNativeAggregateCompiler.UNKNOWN, row.id(0));
		assertTrue(row.bind(0, valueId));
		LmdbNativeKernelHooks hooks = hooks(row,
				AggregateSpec.groupConcat("all", 0, false, "🧩"),
				AggregateSpec.groupConcat("distinct", 0, true, "🧩"));
		long beforeRows = manager.usedBytes();
		try {
			for (int rowIndex = 0; rowIndex < 40; rowIndex++) {
				hooks.accumulateRow(0, 0);
				hooks.accumulateRow(1, 0);
			}
			assertTrue(manager.usedBytes() > beforeRows,
					"both the spilled full result and exact DISTINCT ownership must remain charged");
			row.cancellation.requestCancellation();
			assertThrows(KernelQueryCancelledException.class, () -> hooks.rowAggregateResult(0, 0),
					"cancelled serial GROUP_CONCAT must not publish its materialized Unicode value");
			assertTrue(row.cancellation.isCancellationRequested(), "the failure is terminal query cancellation");
		} finally {
			close(hooks, row, source);
		}
		assertEquals(0L, manager.usedBytes(),
				"cancellation closes the spill, DISTINCT state, decoder cache, and hook reservation");
	}

	private static LmdbQueryMemoryManager installManager() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		return manager;
	}

	private static SyntheticValueSource source() {
		return new SyntheticValueSource(new NumericSource(), PlanValueCatalog.EMPTY).forEvaluation();
	}

	private static RowState row(SyntheticValueSource source) {
		RowState row = new RowState(source, LAYOUT, EmptyBindingSet.getInstance());
		Arrays.fill(row.slots, LmdbNativeAggregateCompiler.UNKNOWN);
		row.recomputeBoundMask();
		return row;
	}

	private static LmdbNativeKernelHooks hooks(RowState row, AggregateSpec... specs) {
		LmdbNativeKernelBindings.AggOut[] outputs = new LmdbNativeKernelBindings.AggOut[specs.length];
		for (int i = 0; i < specs.length; i++) {
			int encoding = switch (specs[i].kind) {
			case SUM, AVG -> LmdbNativeKernelBindings.ENC_EXACT_NUMERIC;
			case SAMPLE, GROUP_CONCAT -> LmdbNativeKernelBindings.ENC_ROW_STATE;
			default -> LmdbNativeKernelBindings.ENC_LONG_COUNT;
			};
			outputs[i] = new LmdbNativeKernelBindings.AggOut(specs[i], encoding);
		}
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0],
				new int[specs.length], List.of(),
				new LmdbNativeKernelBindings.KernelGroupLayout(new int[0], outputs), true, 1);
		return new LmdbNativeKernelHooks(row, bindings);
	}

	private static void close(LmdbNativeKernelHooks hooks, RowState row, SyntheticValueSource source) {
		try {
			hooks.closeFilters();
		} finally {
			row.closeDecodedInputs();
			if (source.executionContext() != null) {
				source.executionContext().close();
			}
		}
	}

	private static void restoreProperty(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	private static NativeSlotLayout layout() {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		return layout;
	}

